// Rumble Roses XX (4B4E07D1): Android port on the ReXGlue SDK.
//
// Based on the WET Android app class (launcher-provided paths, Vulkan GPU plugin) plus the
// one game-specific piece of Revan67/RumbleRosesXX-Recomp's windowed host: a writable PHOTO:
// volume, which the game's photo mode saves to.
//
// Upstream's other host pieces aren't needed here: its four "boundary" functions and the
// memset replacement work around gaps in XenonRecomp's output, and this build is generated by
// the SDK's own codegen, which translates those functions (and the switch tables around them)
// correctly. The physical-heap offset is handled by the SDK's generated memory accessors.

#pragma once

#include <cstdlib>
#include <filesystem>
#include <memory>

#include <rex/cvar.h>
#include <rex/filesystem/devices/host_path_device.h>
#include <rex/filesystem/vfs.h>
#include <rex/logging.h>
#include <rex/rex_app.h>
#include <rex/runtime.h>
#include <rex/system/gpu_plugin.h>

#include "rrxx_patches.h"

// The launcher writes graphics_backend = "any" (WET's game_cvars.h defines it the same way).
REXCVAR_DEFINE_STRING(graphics_backend, "any", "GPU",
                      "Graphics API backend: any, d3d12, vulkan")
    .allowed({"any", "d3d12", "vulkan"});

class RrxxApp : public rex::ReXApp {
 public:
  using rex::ReXApp::ReXApp;

  static std::unique_ptr<rex::ui::WindowedApp> Create(rex::ui::WindowedAppContext& ctx) {
    return std::unique_ptr<RrxxApp>(new RrxxApp(ctx, "rrxx", PPCImageConfig));
  }

  void OnPreSetup(rex::RuntimeConfig& config) override {
    std::string backend = REXCVAR_GET(graphics_backend);
    if (backend != "any" && !config.gpu_plugin.empty()) {
      config.graphics = rex::system::LoadGpuPlugin(config.gpu_plugin, backend);
      if (!config.graphics) {
        REXLOG_WARN("graphics_backend '{}' unavailable, falling back to automatic selection", backend);
      }
    }
  }

  void OnConfigurePaths(rex::PathConfig& paths) override {
    // The launcher (GameActivity) passes --game_data_root (the ISO or an extracted folder),
    // --user_data_root, --cache_root and --config (a toml it regenerates every start).
    if (const char* cfg = std::getenv("REX_CONFIG_PATH"); cfg && *cfg) {
      paths.config_path = cfg;
    }
  }

  // Rumble-XX patches chosen in the launcher (rrxx_* cvars): code-patch switches and the two
  // data patches, applied once the XEX is in guest memory and before the game starts.
  void OnPostLoadXexImage() override { rrxx_patches::Apply(); }

  void OnPostSetup() override {
    // PHOTO: next to the saves, as upstream does (<state>/photo beside <state>/user).
    auto* fs = runtime()->file_system();
    const auto photo_root = runtime()->user_data_root().parent_path() / "photo";
    std::error_code ec;
    std::filesystem::create_directories(photo_root, ec);
    auto photo = std::make_unique<rex::filesystem::HostPathDevice>("\\Device\\RrxxPhoto", photo_root,
                                                                   false, true);
    if (!photo->Initialize() || !fs->RegisterDevice(std::move(photo)) ||
        !fs->RegisterSymbolicLink("PHOTO:", "\\Device\\RrxxPhoto")) {
      REXLOG_ERROR("Couldn't mount the PHOTO: volume at {}", photo_root.string());
    } else {
      REXLOG_INFO("Mounted writable PHOTO: volume at {}", photo_root.string());
    }
  }
};
